import React, { useState } from 'react';
import { useApp } from '../context/AppContext';

export default function Colleges() {
  const { user, selectedCollege, setSelectedCollege, setPage } = useApp();
  const [search, setSearch] = useState('');

  // ✅ Only show student's college
  const colleges =
    user?.role === 'student' && user?.college
      ? [user.college]
      : selectedCollege
      ? [selectedCollege]
      : [];

  return (
    <div style={{ padding: 24 }}>
      {/* 🔥 HEADER */}
      <h1 style={{ fontSize: 26, fontWeight: 800 }}>
        Your College
      </h1>

      {/* 🔥 SEARCH (optional UI only) */}
      <input
        placeholder="Search college..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{
          marginTop: 16,
          padding: 10,
          width: '100%',
          maxWidth: 400,
          borderRadius: 10,
          border: '1px solid #333',
          background: '#0f172a',
          color: '#fff'
        }}
      />

      {/* 🔥 GRID */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
          gap: 20,
          marginTop: 24
        }}
      >
        {colleges.map((c) => (
          <div
            key={c._id}
            onClick={() => {
              setSelectedCollege(c);
              setPage('resources');
            }}
            style={{
              padding: 20,
              borderRadius: 20,
              background: '#0b1120',
              border: '1px solid rgba(255,255,255,0.08)',
              cursor: 'pointer',
              transition: 'all 0.3s ease',
              position: 'relative'
            }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.transform = 'translateY(-5px)')
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.transform = 'translateY(0)')
            }
          >
            {/* 🔥 TOP */}
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <div
                style={{
                  width: 50,
                  height: 50,
                  borderRadius: 12,
                  background: 'rgba(99,102,241,0.2)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 24
                }}
              >
                🏫
              </div>

              <div style={{ color: '#f59e0b', fontWeight: 700 }}>
                ⭐ {c.rating || 4.5}
              </div>
            </div>

            {/* 🔥 SHORT NAME */}
            <div style={{ marginTop: 12, color: '#6366f1', fontSize: 12 }}>
              {c.short}
            </div>

            {/* 🔥 NAME */}
            <h3 style={{ marginTop: 6, fontSize: 16 }}>
              {c.name}
            </h3>

            {/* 🔥 CITY */}
            <p style={{ color: '#94a3b8', fontSize: 13 }}>
              📍 {c.city} · Est. {c.established}
            </p>

            {/* 🔥 TAGS */}
            <div style={{ display: 'flex', gap: 6, marginTop: 10, flexWrap: 'wrap' }}>
              {c.courses?.map((course) => (
                <span
                  key={course}
                  style={{
                    fontSize: 11,
                    padding: '3px 8px',
                    borderRadius: 20,
                    background: 'rgba(255,255,255,0.08)',
                    color: '#cbd5f5'
                  }}
                >
                  {course}
                </span>
              ))}
            </div>

            {/* 🔥 FOOTER */}
            <div
              style={{
                marginTop: 14,
                paddingTop: 10,
                borderTop: '1px solid rgba(255,255,255,0.05)',
                display: 'flex',
                justifyContent: 'space-between',
                fontSize: 13,
                color: '#94a3b8'
              }}
            >
              <span>View resources</span>
              <span style={{ color: '#6366f1' }}>→</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
